-- A plain-text "what happened" recap -- request, work, outcome -- composed in code from the same
-- facts the review's overview renders, and NEVER sent to Ollama: see
-- TraceAnalysisPromptBuilder#buildTraceSummary for why a narrated retelling is not asked of the
-- model. Shown ahead of the model's own findings so a reader re-opening a trace can re-orient
-- before reading verdicts, instead of reconstructing "what was this even about" by hand.
--
-- NULLABLE DEFAULT NULL: every row written before this column existed was generated by a build that
-- never computed it, and there is no way to reconstruct one after the fact without re-running the
-- trace through the current builder -- null here means "not available for this stored analysis",
-- not "this trace had nothing to summarize".
ALTER TABLE trace_analyses ADD COLUMN summary TEXT;
